-- Phase 2.2B: owner-scoped global OSINT, scheduled collection, triage and explicit Investigation links.
-- This additive migration intentionally retains nullable project_id as legacy provenance.
begin;
create type public.research_feed_trigger_type as enum ('MANUAL','SCHEDULED');

alter table public.research_feed_sources add column owner_id uuid references auth.users(id) on delete cascade,
 add column scheduler_enabled boolean not null default true,
 add column fetch_interval_minutes integer not null default 15,
 add column next_scheduled_fetch_at timestamptz,
 add column last_scheduled_fetch_at timestamptz,
 add column scheduling_updated_at timestamptz not null default now();
alter table public.research_feed_fetch_runs add column owner_id uuid references auth.users(id) on delete cascade,
 add column trigger_type public.research_feed_trigger_type not null default 'MANUAL';
alter table public.research_items add column owner_id uuid references auth.users(id) on delete cascade;
alter table public.research_item_fingerprints add column owner_id uuid references auth.users(id) on delete cascade;
alter table public.research_feed_item_observations add column owner_id uuid references auth.users(id) on delete cascade;

update public.research_feed_sources s set owner_id=p.owner_id from public.projects p where p.id=s.project_id;
update public.research_feed_fetch_runs r set owner_id=p.owner_id from public.projects p where p.id=r.project_id;
update public.research_items i set owner_id=p.owner_id from public.projects p where p.id=i.project_id;
update public.research_item_fingerprints f set owner_id=p.owner_id from public.projects p where p.id=f.project_id;
update public.research_feed_item_observations o set owner_id=p.owner_id from public.projects p where p.id=o.project_id;
do $$begin
 if exists(select 1 from public.research_feed_sources where owner_id is null) or exists(select 1 from public.research_feed_fetch_runs where owner_id is null) or exists(select 1 from public.research_items where owner_id is null) or exists(select 1 from public.research_item_fingerprints where owner_id is null) or exists(select 1 from public.research_feed_item_observations where owner_id is null) then raise exception 'PHASE_2_2B_OWNER_BACKFILL_FAILED'; end if;
end$$;

-- Owner keys supersede legacy project-composite keys; project_id remains provenance.
do $$declare c record;begin for c in select conrelid::regclass rel,conname from pg_constraint where contype='f' and conrelid in ('public.research_item_fingerprints'::regclass,'public.research_feed_item_observations'::regclass) loop execute format('alter table %s drop constraint %I',c.rel,c.conname);end loop;end$$;

-- Resolve owner-local duplicate components by fingerprint. Recursive connectivity handles URL/content chains.
create temporary table osint_item_survivors on commit drop as
with recursive edges as (
 select distinct a.owner_id,a.research_item_id a,b.research_item_id b
 from public.research_item_fingerprints a join public.research_item_fingerprints b using(owner_id,fingerprint_type,fingerprint_hash)
 where a.research_item_id<>b.research_item_id
), reach(owner_id,item_id,member_id) as (
 select owner_id,a,a from edges union select owner_id,a,b from edges
 union select r.owner_id,r.item_id,e.b from reach r join edges e on e.owner_id=r.owner_id and e.a=r.member_id
), members as (select owner_id,item_id,member_id from reach union select owner_id,id,id from public.research_items), ranked as (
 select m.owner_id,m.member_id,first_value(m.member_id) over(partition by m.owner_id,m.item_id order by i.created_at,i.id) survivor
 from members m join public.research_items i on i.owner_id=m.owner_id and i.id=m.member_id
)
select owner_id,member_id,min(survivor::text)::uuid survivor from ranked group by owner_id,member_id;

update public.research_items s set first_seen_at=x.first_seen,last_seen_at=x.last_seen
from (select m.owner_id,m.survivor,min(i.first_seen_at) first_seen,max(i.last_seen_at) last_seen from osint_item_survivors m join public.research_items i on i.id=m.member_id and i.owner_id=m.owner_id group by m.owner_id,m.survivor)x
where s.id=x.survivor and s.owner_id=x.owner_id;
update public.research_item_fingerprints f set research_item_id=m.survivor from osint_item_survivors m where f.owner_id=m.owner_id and f.research_item_id=m.member_id and m.member_id<>m.survivor;
delete from public.research_item_fingerprints a using public.research_item_fingerprints b where a.owner_id=b.owner_id and a.fingerprint_type=b.fingerprint_type and a.fingerprint_hash=b.fingerprint_hash and a.id>b.id;

-- Repoint in place, preserving every metadata field. Only newly colliding source/item rows are combined.
update public.research_feed_item_observations o set research_item_id=m.survivor
from osint_item_survivors m where o.owner_id=m.owner_id and o.research_item_id=m.member_id and m.member_id<>m.survivor;
with ranked as (select o.*,row_number() over(partition by owner_id,feed_source_id,research_item_id order by last_seen_at desc,id desc) rn,
 min(first_seen_at) over(partition by owner_id,feed_source_id,research_item_id) merged_first,
 max(last_seen_at) over(partition by owner_id,feed_source_id,research_item_id) merged_last,
 sum(observation_count) over(partition by owner_id,feed_source_id,research_item_id) merged_count,
 min(created_at) over(partition by owner_id,feed_source_id,research_item_id) merged_created,
 max(updated_at) over(partition by owner_id,feed_source_id,research_item_id) merged_updated
 from public.research_feed_item_observations o), updated as (
 update public.research_feed_item_observations o set first_seen_at=r.merged_first,last_seen_at=r.merged_last,observation_count=r.merged_count,created_at=r.merged_created,updated_at=r.merged_updated
 from ranked r where r.id=o.id and r.rn=1 returning o.id)
delete from public.research_feed_item_observations o using ranked r where o.id=r.id and r.rn>1;
delete from public.research_items i using osint_item_survivors m where i.owner_id=m.owner_id and i.id=m.member_id and m.member_id<>m.survivor;

do $$begin
 if exists(select 1 from public.research_item_fingerprints f left join public.research_items i on i.id=f.research_item_id and i.owner_id=f.owner_id where i.id is null) then raise exception 'PHASE_2_2B_ORPHAN_FINGERPRINT';end if;
 if exists(select 1 from public.research_feed_item_observations o left join public.research_items i on i.id=o.research_item_id and i.owner_id=o.owner_id where i.id is null) then raise exception 'PHASE_2_2B_ORPHAN_OBSERVATION';end if;
end$$;

alter table public.research_feed_sources alter column owner_id set not null,alter column project_id drop not null,add constraint research_feed_interval_check check(fetch_interval_minutes in(15,30,60,360,1440)),add unique(owner_id,id);
alter table public.research_feed_fetch_runs alter column owner_id set not null,alter column project_id drop not null,add unique(owner_id,id);
alter table public.research_items alter column owner_id set not null,alter column project_id drop not null,add unique(owner_id,id);
alter table public.research_item_fingerprints alter column owner_id set not null,alter column project_id drop not null,add unique(owner_id,fingerprint_type,fingerprint_hash);
alter table public.research_feed_item_observations alter column owner_id set not null,alter column project_id drop not null,add unique(owner_id,feed_source_id,research_item_id);
create index research_items_owner_effective_idx on public.research_items(owner_id,coalesce(published_at,first_seen_at) desc,id desc);
alter table public.research_items add column search_vector tsvector generated always as (to_tsvector('simple',coalesce(title,'')||' '||coalesce(summary_text,'')||' '||coalesce(content_text,''))) stored;
create index research_items_search_idx on public.research_items using gin(search_vector);

create table public.osint_item_states(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,research_item_id uuid not null,read_at timestamptz,saved_at timestamptz,dismissed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,research_item_id),foreign key(owner_id,research_item_id) references public.research_items(owner_id,id) on delete cascade);
create table public.osint_investigation_links(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,research_item_id uuid not null,project_id uuid not null,analyst_note text not null default '' check(char_length(analyst_note)<=2000),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(owner_id,research_item_id,project_id),foreign key(owner_id,research_item_id) references public.research_items(owner_id,id) on delete cascade,foreign key(project_id) references public.projects(id) on delete cascade);
create function public.osint_link_owner_guard() returns trigger language plpgsql set search_path='' as $$begin if not exists(select 1 from public.projects where id=new.project_id and owner_id=new.owner_id) or new.created_by<>new.owner_id then raise exception 'not_found' using errcode='P0002';end if;return new;end$$;
create trigger osint_link_owner_guard before insert or update on public.osint_investigation_links for each row execute function public.osint_link_owner_guard();

-- Owner-scoped feed administration.
-- Compatibility triggers keep immutable Phase 2.2A project-scoped RPCs operational.
create function public.research_owner_fill() returns trigger language plpgsql security definer set search_path='' as $$begin if new.owner_id is null then if tg_table_name='research_feed_sources' then select owner_id into new.owner_id from public.projects where id=new.project_id;elsif tg_table_name='research_feed_fetch_runs' then select owner_id into new.owner_id from public.research_feed_sources where id=new.feed_source_id;elsif tg_table_name='research_items' then new.owner_id:=new.created_by;elsif tg_table_name='research_item_fingerprints' then select owner_id into new.owner_id from public.research_items where id=new.research_item_id;else select owner_id into new.owner_id from public.research_feed_sources where id=new.feed_source_id;end if;end if;return new;end$$;
do $$declare t text;begin foreach t in array array['research_feed_sources','research_feed_fetch_runs','research_items','research_item_fingerprints','research_feed_item_observations']loop execute format('create trigger %I before insert on public.%I for each row execute function public.research_owner_fill()',t||'_owner_fill',t);end loop;end$$;

create function public.create_global_research_feed(p_actor_id uuid,p_name text,p_description text,p_configured_url text,p_configured_url_hash text,p_enabled boolean,p_scheduler_enabled boolean,p_interval integer) returns public.research_feed_sources language plpgsql security definer set search_path='' as $$declare r public.research_feed_sources;begin
 if p_actor_id is null or p_interval not in(15,30,60,360,1440) or char_length(trim(p_name)) not between 1 and 240 or char_length(p_description)>10000 or char_length(p_configured_url)>4096 or p_configured_url_hash!~'^[0-9a-f]{64}$' then raise exception 'INVALID_FEED_INPUT' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_actor_id::text||':global-feed-limit',0));if(select count(*) from public.research_feed_sources where owner_id=p_actor_id and archived_at is null)>=100 then raise exception 'FEED_LIMIT';end if;
 insert into public.research_feed_sources(owner_id,project_id,name,description,configured_url,configured_url_hash,enabled,scheduler_enabled,fetch_interval_minutes,next_scheduled_fetch_at,created_by) values(p_actor_id,null,trim(p_name),p_description,p_configured_url,p_configured_url_hash,p_enabled,p_scheduler_enabled,p_interval,case when p_enabled and p_scheduler_enabled then clock_timestamp() end,p_actor_id)returning * into r;return r;end$$;
create function public.edit_global_research_feed(p_actor_id uuid,p_feed_source_id uuid,p_name text,p_description text,p_configured_url text,p_configured_url_hash text,p_enabled boolean,p_scheduler_enabled boolean,p_interval integer) returns public.research_feed_sources language plpgsql security definer set search_path='' as $$declare r public.research_feed_sources;changed boolean;begin select * into r from public.research_feed_sources where owner_id=p_actor_id and id=p_feed_source_id for update;if r.id is null then raise exception 'not_found' using errcode='P0002';end if;if r.archived_at is not null or r.fetch_lease_expires_at>clock_timestamp() then raise exception 'FEED_UNAVAILABLE';end if;if p_interval not in(15,30,60,360,1440) or char_length(trim(p_name)) not between 1 and 240 or char_length(p_description)>10000 or(p_configured_url is not null and(p_configured_url_hash!~'^[0-9a-f]{64}$' or char_length(p_configured_url)>4096))then raise exception 'INVALID_FEED_INPUT';end if;changed:=p_configured_url_hash is not null and p_configured_url_hash<>r.configured_url_hash;update public.research_feed_sources set name=trim(p_name),description=p_description,configured_url=coalesce(p_configured_url,configured_url),configured_url_hash=coalesce(p_configured_url_hash,configured_url_hash),enabled=p_enabled,scheduler_enabled=p_scheduler_enabled,fetch_interval_minutes=p_interval,next_scheduled_fetch_at=case when p_enabled and p_scheduler_enabled then coalesce(next_scheduled_fetch_at,clock_timestamp()) end,detected_feed_type=case when changed then 'UNKNOWN' else detected_feed_type end,health_status=case when changed then 'NEVER_FETCHED' else health_status end,last_final_url=case when changed then null else last_final_url end,etag=case when changed then null else etag end,last_modified=case when changed then null else last_modified end,last_error_code=case when changed then null else last_error_code end,last_error_message=case when changed then null else last_error_message end,scheduling_updated_at=clock_timestamp(),updated_at=clock_timestamp() where id=r.id returning * into r;return r;end$$;
create function public.set_global_research_feed_state(p_actor_id uuid,p_feed_source_id uuid,p_enabled boolean,p_scheduler_enabled boolean,p_interval integer) returns public.research_feed_sources language plpgsql security definer set search_path='' as $$declare r public.research_feed_sources;begin if p_interval not in(15,30,60,360,1440)then raise exception 'INVALID_INTERVAL';end if;update public.research_feed_sources set enabled=p_enabled,scheduler_enabled=p_scheduler_enabled,fetch_interval_minutes=p_interval,next_scheduled_fetch_at=case when p_enabled and p_scheduler_enabled then coalesce(next_scheduled_fetch_at,clock_timestamp()) end,scheduling_updated_at=clock_timestamp(),updated_at=clock_timestamp() where owner_id=p_actor_id and id=p_feed_source_id and archived_at is null returning * into r;if r.id is null then raise exception 'not_found' using errcode='P0002';end if;return r;end$$;
create function public.archive_global_research_feed(p_actor_id uuid,p_feed_source_id uuid) returns public.research_feed_sources language plpgsql security definer set search_path='' as $$declare r public.research_feed_sources;begin update public.research_feed_sources set enabled=false,scheduler_enabled=false,next_scheduled_fetch_at=null,archived_at=coalesce(archived_at,clock_timestamp()),updated_at=clock_timestamp() where owner_id=p_actor_id and id=p_feed_source_id and(fetch_lease_expires_at is null or fetch_lease_expires_at<=clock_timestamp())returning * into r;if r.id is null then raise exception 'not_found' using errcode='P0002';end if;return r;end$$;
create function public.restore_global_research_feed(p_actor_id uuid,p_feed_source_id uuid) returns public.research_feed_sources language plpgsql security definer set search_path='' as $$declare r public.research_feed_sources;begin update public.research_feed_sources set enabled=false,scheduler_enabled=false,next_scheduled_fetch_at=null,archived_at=null,updated_at=clock_timestamp() where owner_id=p_actor_id and id=p_feed_source_id and archived_at is not null returning * into r;if r.id is null then raise exception 'not_found' using errcode='P0002';end if;return r;end$$;

-- This helper is called only while its source row is locked.
create function public.start_global_feed_run(p_owner_id uuid,p_feed_source_id uuid,p_trigger_type public.research_feed_trigger_type) returns table(feed_source_id uuid,owner_id uuid,run_id uuid,lease_token uuid,request_url_hash text,lease_expires_at timestamptz,configured_url text,etag text,last_modified text) language plpgsql security definer set search_path='' as $$declare s public.research_feed_sources;t uuid:=gen_random_uuid();rid uuid:=gen_random_uuid();exp timestamptz:=clock_timestamp()+interval '2 minutes';begin select src.* into s from public.research_feed_sources src where src.owner_id=p_owner_id and src.id=p_feed_source_id for update;if s.id is null or not s.enabled or s.archived_at is not null or s.fetch_lease_expires_at>clock_timestamp() then raise exception 'FEED_UNAVAILABLE';end if;if s.fetch_lease_run_id is not null then update public.research_feed_fetch_runs set status='FAILED',completed_at=clock_timestamp(),error_code='LEASE_EXPIRED',error_message='The prior fetch lease expired.' where id=s.fetch_lease_run_id and owner_id=p_owner_id and status='RUNNING';end if;insert into public.research_feed_fetch_runs(id,owner_id,project_id,feed_source_id,request_url_hash,lease_token_hash,lease_expires_at,created_by,trigger_type)values(rid,p_owner_id,s.project_id,s.id,s.configured_url_hash,encode(public.digest(t::text,'sha256'),'hex'),exp,p_owner_id,p_trigger_type);update public.research_feed_sources set fetch_lease_token_hash=encode(public.digest(t::text,'sha256'),'hex'),fetch_lease_run_id=rid,fetch_lease_url_hash=s.configured_url_hash,fetch_lease_expires_at=exp where id=s.id;return query select s.id,p_owner_id,rid,t,s.configured_url_hash,exp,s.configured_url,s.etag,s.last_modified;end$$;
create function public.claim_global_research_feed_fetch(p_actor_id uuid,p_feed_source_id uuid,p_trigger_type public.research_feed_trigger_type) returns table(feed_source_id uuid,owner_id uuid,run_id uuid,lease_token uuid,request_url_hash text,lease_expires_at timestamptz,configured_url text,etag text,last_modified text) language plpgsql security definer set search_path='' as $$begin return query select * from public.start_global_feed_run(p_actor_id,p_feed_source_id,p_trigger_type);end$$;
create function public.claim_due_global_research_feed_fetches(p_limit integer) returns table(feed_source_id uuid,owner_id uuid,run_id uuid,lease_token uuid,request_url_hash text,lease_expires_at timestamptz,configured_url text,etag text,last_modified text) language plpgsql security definer set search_path='' as $$declare s record;begin if p_limit not between 1 and 20 then raise exception 'INVALID_BATCH_SIZE';end if;for s in select src.id,src.owner_id from public.research_feed_sources src where src.enabled and src.scheduler_enabled and src.archived_at is null and src.next_scheduled_fetch_at<=clock_timestamp() and(src.fetch_lease_expires_at is null or src.fetch_lease_expires_at<=clock_timestamp())order by src.next_scheduled_fetch_at,src.id for update skip locked limit p_limit loop return query select * from public.start_global_feed_run(s.owner_id,s.id,'SCHEDULED');end loop;end$$;

create function public.complete_global_research_feed_fetch(p_owner_id uuid,p_feed_source_id uuid,p_run_id uuid,p_lease_token uuid,p_request_url_hash text,p_status public.research_feed_run_status,p_feed_type public.research_feed_type,p_final_url text,p_http_status integer,p_response_bytes integer,p_etag text,p_last_modified text,p_items jsonb default '[]') returns public.research_feed_fetch_runs language plpgsql security definer set search_path='' as $$declare s public.research_feed_sources;r public.research_feed_fetch_runs;j jsonb;u uuid;url_match uuid;content_match uuid;ts timestamptz:=clock_timestamp();cats text[];begin select * into s from public.research_feed_sources where owner_id=p_owner_id and id=p_feed_source_id for update;select * into r from public.research_feed_fetch_runs where owner_id=p_owner_id and id=p_run_id and feed_source_id=p_feed_source_id for update;if s.id is null or r.id is null or r.status<>'RUNNING' or s.fetch_lease_run_id<>p_run_id or s.fetch_lease_token_hash<>encode(public.digest(p_lease_token::text,'sha256'),'hex') or r.lease_token_hash<>encode(public.digest(p_lease_token::text,'sha256'),'hex') or s.fetch_lease_url_hash<>p_request_url_hash or s.configured_url_hash<>p_request_url_hash or r.request_url_hash<>p_request_url_hash or s.fetch_lease_expires_at<=ts or r.lease_expires_at<=ts then raise exception 'STALE_FETCH_LEASE';end if;if p_status not in('SUCCEEDED','NOT_MODIFIED') or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)>500 then raise exception 'INVALID_COMPLETION';end if;if p_status='SUCCEEDED' then for j in select * from jsonb_array_elements(p_items) loop cats:=array(select value from jsonb_array_elements_text(coalesce(j->'categories','[]'))value);select research_item_id into url_match from public.research_item_fingerprints where owner_id=p_owner_id and fingerprint_type='URL' and fingerprint_hash=j->>'url_hash';select research_item_id into content_match from public.research_item_fingerprints where owner_id=p_owner_id and fingerprint_type='CONTENT' and fingerprint_hash=j->>'content_hash';if url_match is not null and content_match is not null and url_match<>content_match then continue;end if;u:=coalesce(url_match,content_match);if u is null then insert into public.research_items(owner_id,project_id,canonical_url,title,summary_text,content_text,author_name,published_at,source_updated_at,language,categories,created_by)values(p_owner_id,s.project_id,j->>'canonical_url',j->>'title',j->>'summary_text',j->>'content_text',j->>'author_name',nullif(j->>'published_at','')::timestamptz,nullif(j->>'source_updated_at','')::timestamptz,j->>'language',cats,p_owner_id)returning id into u;insert into public.research_item_fingerprints(owner_id,project_id,research_item_id,fingerprint_type,fingerprint_hash)values(p_owner_id,s.project_id,u,'CONTENT',j->>'content_hash');else update public.research_items set last_seen_at=ts,updated_at=ts where owner_id=p_owner_id and id=u;insert into public.research_item_fingerprints(owner_id,project_id,research_item_id,fingerprint_type,fingerprint_hash)values(p_owner_id,s.project_id,u,'CONTENT',j->>'content_hash')on conflict(owner_id,fingerprint_type,fingerprint_hash)do nothing;end if;if j->>'url_hash' is not null then insert into public.research_item_fingerprints(owner_id,project_id,research_item_id,fingerprint_type,fingerprint_hash)values(p_owner_id,s.project_id,u,'URL',j->>'url_hash')on conflict(owner_id,fingerprint_type,fingerprint_hash)do nothing;end if;insert into public.research_feed_item_observations(owner_id,project_id,feed_source_id,research_item_id,fetch_run_id,external_item_id,observed_url,source_published_at)values(p_owner_id,s.project_id,s.id,u,p_run_id,j->>'external_id',j->>'canonical_url',nullif(j->>'published_at','')::timestamptz)on conflict(owner_id,feed_source_id,research_item_id)do update set fetch_run_id=excluded.fetch_run_id,last_seen_at=ts,observation_count=public.research_feed_item_observations.observation_count+1,updated_at=ts;end loop;end if;update public.research_feed_fetch_runs set status=p_status,completed_at=ts,duration_ms=greatest(0,(extract(epoch from(ts-started_at))*1000)::int),final_url=p_final_url,http_status=p_http_status,response_bytes=p_response_bytes where id=p_run_id returning * into r;update public.research_feed_sources set detected_feed_type=case when p_status='SUCCEEDED' then p_feed_type else detected_feed_type end,health_status='HEALTHY',last_checked_at=ts,last_success_at=ts,last_scheduled_fetch_at=case when r.trigger_type='SCHEDULED' then ts else last_scheduled_fetch_at end,next_scheduled_fetch_at=case when enabled and scheduler_enabled then ts+make_interval(mins=>fetch_interval_minutes) end,etag=case when p_status='SUCCEEDED' then nullif(p_etag,'') else etag end,last_modified=case when p_status='SUCCEEDED' then nullif(p_last_modified,'') else last_modified end,consecutive_failures=0,last_error_code=null,last_error_message=null,fetch_lease_token_hash=null,fetch_lease_run_id=null,fetch_lease_url_hash=null,fetch_lease_expires_at=null,updated_at=ts where id=p_feed_source_id and fetch_lease_run_id=p_run_id;return r;end$$;
create function public.fail_global_research_feed_fetch(p_owner_id uuid,p_feed_source_id uuid,p_run_id uuid,p_lease_token uuid,p_request_url_hash text,p_error_code text,p_error_message text) returns void language plpgsql security definer set search_path='' as $$declare s public.research_feed_sources;r public.research_feed_fetch_runs;ts timestamptz:=clock_timestamp();begin select * into s from public.research_feed_sources where owner_id=p_owner_id and id=p_feed_source_id for update;select * into r from public.research_feed_fetch_runs where owner_id=p_owner_id and id=p_run_id and feed_source_id=p_feed_source_id for update;if s.id is null or r.id is null or r.status<>'RUNNING' or s.fetch_lease_run_id<>p_run_id or s.fetch_lease_token_hash<>encode(public.digest(p_lease_token::text,'sha256'),'hex') or s.fetch_lease_url_hash<>p_request_url_hash or r.request_url_hash<>p_request_url_hash then raise exception 'STALE_FETCH_LEASE';end if;update public.research_feed_fetch_runs set status='FAILED',completed_at=ts,error_code=left(p_error_code,64),error_message=left(p_error_message,500)where id=p_run_id;update public.research_feed_sources set last_checked_at=ts,last_scheduled_fetch_at=case when r.trigger_type='SCHEDULED' then ts else last_scheduled_fetch_at end,consecutive_failures=consecutive_failures+1,health_status=case when consecutive_failures+1>=3 then 'ERROR'::public.research_feed_health else 'DEGRADED'::public.research_feed_health end,last_error_code=left(p_error_code,64),last_error_message=left(p_error_message,500),next_scheduled_fetch_at=case when enabled and scheduler_enabled then ts+least(interval '24 hours',make_interval(mins=>fetch_interval_minutes*power(2,least(consecutive_failures,10))::int))end,fetch_lease_token_hash=null,fetch_lease_run_id=null,fetch_lease_url_hash=null,fetch_lease_expires_at=null,updated_at=ts where id=p_feed_source_id and fetch_lease_run_id=p_run_id;end$$;

create function public.list_osint_feed(p_mode text default 'all',p_source_id uuid default null,p_from date default null,p_to date default null,p_search text default null,p_cursor_at timestamptz default null,p_cursor_id uuid default null,p_limit integer default 30) returns table(id uuid,title text,summary_text text,canonical_url text,categories text[],effective_at timestamptz,primary_source text,additional_source_count bigint,read_at timestamptz,saved_at timestamptz,dismissed_at timestamptz,linked_count bigint) language sql stable security invoker set search_path='' as $$
 with eligible as(select i.* ,coalesce(i.published_at,i.first_seen_at) effective from public.research_items i left join public.osint_item_states st on st.owner_id=i.owner_id and st.research_item_id=i.id where i.owner_id=auth.uid() and p_mode in('all','unread','saved','dismissed') and(p_mode='dismissed' and st.dismissed_at is not null or p_mode<>'dismissed' and st.dismissed_at is null and(p_mode<>'unread' or st.read_at is null)and(p_mode<>'saved' or st.saved_at is not null))and(p_source_id is null or exists(select 1 from public.research_feed_item_observations o where o.owner_id=i.owner_id and o.research_item_id=i.id and o.feed_source_id=p_source_id))and(p_from is null or coalesce(i.published_at,i.first_seen_at)>=p_from::timestamptz)and(p_to is null or coalesce(i.published_at,i.first_seen_at)<(p_to+1)::timestamptz)and(p_search is null or i.search_vector@@websearch_to_tsquery('simple',left(p_search,200)))and(p_cursor_at is null or(coalesce(i.published_at,i.first_seen_at),i.id)<(p_cursor_at,p_cursor_id))order by effective desc,i.id desc limit least(greatest(p_limit,1),30))
 select e.id,e.title,e.summary_text,e.canonical_url,e.categories,e.effective,(select s.name from public.research_feed_item_observations o join public.research_feed_sources s on s.owner_id=o.owner_id and s.id=o.feed_source_id where o.owner_id=e.owner_id and o.research_item_id=e.id order by o.first_seen_at,s.id limit 1),(select greatest(count(*)-1,0) from public.research_feed_item_observations o where o.owner_id=e.owner_id and o.research_item_id=e.id),st.read_at,st.saved_at,st.dismissed_at,(select count(*) from public.osint_investigation_links l where l.owner_id=e.owner_id and l.research_item_id=e.id) from eligible e left join public.osint_item_states st on st.owner_id=e.owner_id and st.research_item_id=e.id order by e.effective desc,e.id desc
$$;
grant execute on function public.list_osint_feed(text,uuid,date,date,text,timestamptz,uuid,integer) to authenticated;

-- Owner policies replace project policies. Workflow tables remain read-only to ordinary clients.
do $$declare t text;p record;begin foreach t in array array['research_feed_sources','research_feed_fetch_runs','research_items','research_item_fingerprints','research_feed_item_observations'] loop for p in select policyname from pg_policies where schemaname='public' and tablename=t loop execute format('drop policy %I on public.%I',p.policyname,t);end loop;execute format('create policy %I on public.%I for select to authenticated using(auth.uid()=owner_id)',t||'_owner_select',t);end loop;end$$;
alter table public.osint_item_states enable row level security;alter table public.osint_investigation_links enable row level security;
create policy osint_states_owner on public.osint_item_states for all to authenticated using(auth.uid()=owner_id) with check(auth.uid()=owner_id and exists(select 1 from public.research_items i where i.id=research_item_id and i.owner_id=auth.uid()));
create policy osint_links_owner_select on public.osint_investigation_links for select to authenticated using(auth.uid()=owner_id);create policy osint_links_owner_insert on public.osint_investigation_links for insert to authenticated with check(auth.uid()=owner_id and created_by=auth.uid());create policy osint_links_owner_delete on public.osint_investigation_links for delete to authenticated using(auth.uid()=owner_id);
revoke all on public.osint_item_states,public.osint_investigation_links from anon;grant select,insert,update,delete on public.osint_item_states to authenticated;grant select,insert,delete on public.osint_investigation_links to authenticated;

alter table public.research_feed_fetch_runs add foreign key(owner_id,feed_source_id) references public.research_feed_sources(owner_id,id) on delete cascade;
alter table public.research_item_fingerprints add foreign key(owner_id,research_item_id) references public.research_items(owner_id,id) on delete cascade;
alter table public.research_feed_item_observations add foreign key(owner_id,feed_source_id) references public.research_feed_sources(owner_id,id),add foreign key(owner_id,research_item_id) references public.research_items(owner_id,id),add foreign key(owner_id,fetch_run_id) references public.research_feed_fetch_runs(owner_id,id);
do $$begin if exists(select 1 from public.research_feed_item_observations o join public.research_feed_sources s on s.id=o.feed_source_id where s.owner_id<>o.owner_id) or exists(select 1 from public.research_feed_item_observations o join public.research_items i on i.id=o.research_item_id where i.owner_id<>o.owner_id) or exists(select 1 from public.research_item_fingerprints f join public.research_items i on i.id=f.research_item_id where i.owner_id<>f.owner_id) then raise exception 'PHASE_2_2B_CROSS_OWNER_REFERENCE';end if;if exists(select 1 from public.research_item_fingerprints group by owner_id,fingerprint_type,fingerprint_hash having count(*)>1)or exists(select 1 from public.research_feed_item_observations group by owner_id,feed_source_id,research_item_id having count(*)>1)then raise exception 'PHASE_2_2B_DUPLICATE_INVARIANT';end if;end$$;
revoke all on function public.create_global_research_feed(uuid,text,text,text,text,boolean,boolean,integer),public.edit_global_research_feed(uuid,uuid,text,text,text,text,boolean,boolean,integer),public.set_global_research_feed_state(uuid,uuid,boolean,boolean,integer),public.archive_global_research_feed(uuid,uuid),public.restore_global_research_feed(uuid,uuid),public.claim_global_research_feed_fetch(uuid,uuid,public.research_feed_trigger_type),public.claim_due_global_research_feed_fetches(integer),public.complete_global_research_feed_fetch(uuid,uuid,uuid,uuid,text,public.research_feed_run_status,public.research_feed_type,text,integer,integer,text,text,jsonb),public.fail_global_research_feed_fetch(uuid,uuid,uuid,uuid,text,text,text) from public,anon,authenticated;
grant execute on function public.create_global_research_feed(uuid,text,text,text,text,boolean,boolean,integer),public.edit_global_research_feed(uuid,uuid,text,text,text,text,boolean,boolean,integer),public.set_global_research_feed_state(uuid,uuid,boolean,boolean,integer),public.archive_global_research_feed(uuid,uuid),public.restore_global_research_feed(uuid,uuid),public.claim_global_research_feed_fetch(uuid,uuid,public.research_feed_trigger_type),public.claim_due_global_research_feed_fetches(integer),public.complete_global_research_feed_fetch(uuid,uuid,uuid,uuid,text,public.research_feed_run_status,public.research_feed_type,text,integer,integer,text,text,jsonb),public.fail_global_research_feed_fetch(uuid,uuid,uuid,uuid,text,text,text) to service_role;

update public.research_feed_sources set next_scheduled_fetch_at=case when enabled and archived_at is null then clock_timestamp() else null end;
commit;
